 const palettes={digikala:['#ef233c','#a50020'],snappshop:['#08a76b','#00613e'],torob:['#23c6d4','#087d9c'],basalam:['#9360e8','#5524ad'],memarket:['#f59e0b','#a34b05']};
 const logos={digikala:'دیجی کالا.webp',snappshop:'اسنپ شاپ.webp',torob:'ترب.webp',basalam:'باسلام.webp'};
