  if(id==='torob')return '<svg viewBox="0 0 240 180" aria-hidden="true"><path d="M31 129q26-51 54-40l20 19 31-57q13-22 28-6l37 42" fill="none" stroke="#fff" stroke-width="8" stroke-linecap="round"/><rect x="57" y="94" width="125" height="68" rx="15" fill="#12aeca"/><path d="M79 112h81M79 128h56" stroke="#d9fbff" stroke-width="6" stroke-linecap="round"/><circle cx="175" cy="48" r="31" fill="#fff"/><text x="175" y="59" text-anchor="middle" font-size="32" font-weight="900" fill="#0aa5a5">٪</text><path d="M25 47h52M25 60h32" stroke="#fff" stroke-width="6" stroke-linecap="round" opacity=".7"/></svg>';
